//! Bakes the identifier prefix (scripts/spool-id.sh) into the crate as `SPOOL_ID_PREFIX`, so
//! the broker's Mach service name matches the plists generated by scripts/build-bundle.sh.

use std::path::Path;
use std::process::Command;

const FALLBACK: &str = "local.spool";

fn main() {
    let manifest = std::env::var("CARGO_MANIFEST_DIR").expect("set by cargo");
    let root = Path::new(&manifest).join("../..");
    let script = root.join("scripts/spool-id.sh");

    println!("cargo:rerun-if-env-changed=SPOOL_ID_PREFIX");
    println!("cargo:rerun-if-changed={}", script.display());
    // Re-run when the remote changes. In a worktree the config lives in the common dir.
    if let Ok(out) = Command::new("git").arg("-C").arg(&root).args(["rev-parse", "--git-common-dir"]).output()
        && out.status.success()
    {
        let dir = String::from_utf8_lossy(&out.stdout).trim().to_string();
        let config = root.join(dir).join("config");
        println!("cargo:rerun-if-changed={}", config.display());
    }

    let id = match Command::new("sh").arg(&script).output() {
        Ok(out) if out.status.success() => {
            for line in String::from_utf8_lossy(&out.stderr).lines() {
                println!("cargo:warning={line}");
            }
            String::from_utf8_lossy(&out.stdout).trim().to_string()
        }
        Ok(out) => panic!("{} failed: {}", script.display(), String::from_utf8_lossy(&out.stderr).trim()),
        Err(e) => {
            println!("cargo:warning=cannot run {} ({e}); using {FALLBACK}", script.display());
            FALLBACK.to_string()
        }
    };
    println!("cargo:rustc-env=SPOOL_ID_PREFIX={id}");
}
